insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('09994688-2cdd-46d7-b103-f2fe1497c1f7', '6b53bed4-b795-4ffe-a5ad-48eeffb0f7a7', $$zwangerschapsecho; foto 1; d = 8,052 · √(1,037a) + 23,73 (d in dagen, a in mm), bruikbaar van 8,5 tot 13 weken$$,
   $$wiskunde-b-havo-2023-ii-zwangerschap-context1.png$$,
   $$Een zwangerschapsecho is een afbeelding van een ongeboren baby. Zie foto 1. Een echo wordt onder andere gebruikt om vast te stellen hoe lang een vrouw al zwanger is.
foto 1
Op de echo kan de afstand a van de bovenkant van het hoofdje tot de onderkant van de billen worden gemeten. Met behulp van de volgende formule kan dan de zwangerschapsduur d worden geschat:
d = 8,052 · √(1,037a) + 23,73
De zwangerschapsduur d is in dagen en de gemeten afstand a in mm. Deze formule is alleen bruikbaar bij een zwangerschapsduur van ongeveer 8,5 tot ongeveer 13 weken.$$, 'inline'),
  ('9317d8e4-b729-42bd-a9e6-2fb75ae8f95c', '6b53bed4-b795-4ffe-a5ad-48eeffb0f7a7', $$gemeten a = 55 mm$$,
   $$wiskunde-b-havo-2023-ii-zwangerschap-context2.png$$,
   $$Bij een vrouw wordt een echo gemaakt. Daarbij wordt gemeten a = 55 mm.$$, 'inline'),
  ('50f15b19-d6b9-49dd-b365-2ee44c8c4d5c', '6b53bed4-b795-4ffe-a5ad-48eeffb0f7a7', $$herschreven formule a = p · (q · d − r)²; afgerond p = 0,96, q = 0,12, r = 2,95$$,
   $$wiskunde-b-havo-2023-ii-zwangerschap-context3.png$$,
   $$Als bekend is hoelang een vrouw zwanger is, kan omgekeerd berekend worden wat de afstand a bij de ongeboren baby is. Hiervoor kan de formule worden herschreven door a in d uit te drukken. Dit geeft een formule van de vorm:
a = p · (q · d − r)²
Mogelijke waarden van p, q en r, afgerond op twee decimalen, zijn: p = 0,96, q = 0,12 en r = 2,95.$$, 'inline'),
  ('b1fef466-2292-4ef5-b160-1ac1af92bbb3', '6b53bed4-b795-4ffe-a5ad-48eeffb0f7a7', $$a = 0,96 · (0,12d − 2,95)² bij 8,5 tot 13 weken$$,
   $$wiskunde-b-havo-2023-ii-zwangerschap-context4.png$$,
   $$Bij een zwangerschapsduur van 8,5 tot 13 weken is de afstand bij de ongeboren baby te bepalen volgens de formule a = 0,96 · (0,12d − 2,95)².$$, 'inline'),
  ('ce9ad22a-a70a-49e5-adbd-377b47c5ed66', '6b53bed4-b795-4ffe-a5ad-48eeffb0f7a7', $$vanaf 13 weken: schatting met de hoofdomtrek; foto 2$$,
   $$wiskunde-b-havo-2023-ii-zwangerschap-context5.png$$,
   $$Vanaf 13 weken zwangerschap kan gebruik worden gemaakt van een andere formule voor een schatting van de zwangerschapsduur. Hierbij wordt de hoofdomtrek gebruikt. Op foto 2 is een dwarsdoorsnede te zien van het hoofd.
foto 2$$, 'inline'),
  ('6fe4bd59-515c-4f95-a8f7-84845eabc054', '6b53bed4-b795-4ffe-a5ad-48eeffb0f7a7', $$w = 3,12958 · 1,00244ʰ · h^0,2794 (w in weken, h hoofdomtrek in mm)$$,
   $$wiskunde-b-havo-2023-ii-zwangerschap-context6.png$$,
   $$De formule voor de zwangerschapsduur vanaf 13 weken wordt gegeven door:
w = 3,12958 · 1,00244ʰ · h^0,2794
Hierin is w de zwangerschapsduur in weken en h de hoofdomtrek in mm.$$, 'inline'),
  ('1dec6786-c6fa-4cbf-b12c-cd829cd39165', 'a709ce04-b7d2-497c-9241-f6bfa14312a4', $$lijn l: y = ½x, lijn m: y = −½x; cirkel c met middelpunt M(√5, 0) en straal 1; l raakt c; figuur 1$$,
   $$wiskunde-b-havo-2023-ii-cirkel-tussen-lijnen-context1.png$$,
   $$De lijn l is gegeven door de vergelijking y = ½x en de lijn m door de vergelijking y = −½x. Verder is gegeven de cirkel c met middelpunt M(√5, 0) en straal 1.
Lijn l raakt cirkel c. Zie figuur 1.
figuur 1$$, 'inline'),
  ('168a2583-6929-4b65-9af2-88b2de42803a', 'a709ce04-b7d2-497c-9241-f6bfa14312a4', $$verticale lijn n raakt c rechts; A = n ∩ m, B = n ∩ l; driehoek OAB met ingeschreven cirkel c$$,
   $$wiskunde-b-havo-2023-ii-cirkel-tussen-lijnen-context2.png$$,
   $$De verticale lijn n raakt cirkel c aan de rechterkant. Lijn n snijdt lijn m in punt A en lijn l in punt B. Samen met de oorsprong O vormen de punten A en B de driehoek OAB. Cirkel c past precies in deze driehoek. Zie figuur 2.$$, 'inline'),
  ('b4f77721-c98a-4c21-9d74-9a228755b691', 'a709ce04-b7d2-497c-9241-f6bfa14312a4', $$figuur 2$$,
   $$wiskunde-b-havo-2023-ii-cirkel-tussen-lijnen-context3.png$$,
   $$figuur 2$$, 'inline'),
  ('92820ce6-8514-4195-bff0-728bf3e2db13', '45290ca1-0db4-47d1-9c66-2c137c77f37f', $$f(x) = 16 − x²; P op grafiek van f; raaklijn in P snijdt positieve x-as in A en y-as in B; figuur 1$$,
   $$wiskunde-b-havo-2023-ii-raaklijn-en-driehoeken-context1.png$$,
   $$De functie f wordt gegeven door f(x) = 16 − x². Het punt P ligt op de grafiek van f. De raaklijn aan de grafiek van f in P snijdt de positieve x-as in het punt A en de y-as in het punt B. Zie figuur 1.
figuur 1$$, 'inline'),
  ('eacf3dbc-8a16-4cd6-a3cd-4cf61edf3982', '45290ca1-0db4-47d1-9c66-2c137c77f37f', $$P zo gekozen dat OB = 3 · OA$$,
   $$wiskunde-b-havo-2023-ii-raaklijn-en-driehoeken-context2.png$$,
   $$Punt P is zo gekozen dat geldt: OB = 3 · OA.$$, 'inline'),
  ('18182846-96b6-43ad-9b81-c6dfe29f6f74', '45290ca1-0db4-47d1-9c66-2c137c77f37f', $$C en D snijpunten van f met positieve x-as en y-as; Q(q, f(q)) tussen C en D; driehoeken OCQ en OQD met oppervlakte 2(16 − q²) en 8q; gelijke oppervlaktes; figuur$$,
   $$wiskunde-b-havo-2023-ii-raaklijn-en-driehoeken-context3.png$$,
   $$De grafiek van f snijdt de positieve x-as in het punt C en de y-as in het punt D. Het punt Q ligt op de grafiek van f tussen de punten C en D en heeft x-coördinaat q.
In figuur 2 zijn de grafiek van f en de grijze driehoeken OCQ en OQD weergegeven.
De oppervlakte van de beide driehoeken kan worden uitgedrukt in q. De oppervlakte van driehoek OCQ is 2(16 − q²).
De oppervlakte van driehoek OQD uitgedrukt in q is gelijk aan 8q. Punt Q is zo gekozen dat geldt: de twee driehoeken hebben gelijke oppervlaktes.$$, 'inline'),
  ('d831c5ed-6acb-484c-80c1-96c677d12b7c', '0cfe98ed-2dbd-4d03-b3a7-7fc23b2abb92', $$f(x) = x³ + 6x² − 36x − 88; P en Q toppen; middelste snijpunt met x-as M(−2, 0)$$,
   $$wiskunde-b-havo-2023-ii-een-translatie-en-snijpunten-met-de-x-as-context1.png$$,
   $$De functie f wordt gegeven door f(x) = x³ + 6x² − 36x − 88.
De punten P en Q zijn de toppen van de grafiek van f. Het middelste snijpunt van de grafiek van f met de x-as is het punt M(−2, 0).$$, 'inline'),
  ('3c80c430-385f-4776-9879-6d0a02cb447e', '0cfe98ed-2dbd-4d03-b3a7-7fc23b2abb92', $$figuur 1$$,
   $$wiskunde-b-havo-2023-ii-een-translatie-en-snijpunten-met-de-x-as-context2.png$$,
   $$figuur 1$$, 'inline'),
  ('16219fce-5f17-418a-8fbd-bb11b0519fc7', '0cfe98ed-2dbd-4d03-b3a7-7fc23b2abb92', $$M ligt midden tussen P en Q$$,
   $$wiskunde-b-havo-2023-ii-een-translatie-en-snijpunten-met-de-x-as-context3.png$$,
   $$Punt M ligt midden tussen P en Q.$$, 'inline'),
  ('f3ba17f8-0f6f-442b-ac84-e132df793615', '0cfe98ed-2dbd-4d03-b3a7-7fc23b2abb92', $$g ontstaat door de grafiek van f twee naar rechts te verschuiven; g(x) = x³ − 48x$$,
   $$wiskunde-b-havo-2023-ii-een-translatie-en-snijpunten-met-de-x-as-context4.png$$,
   $$Door de grafiek van f twee naar rechts te verschuiven ontstaat de grafiek van de functie g. Een formule voor g is g(x) = x³ − 48x.$$, 'inline'),
  ('faf2f24f-335f-4179-bf7b-e7572dbd7189', '0cfe98ed-2dbd-4d03-b3a7-7fc23b2abb92', $$figuur 2: grafieken van f en g$$,
   $$wiskunde-b-havo-2023-ii-een-translatie-en-snijpunten-met-de-x-as-context5.png$$,
   $$In figuur 2 zijn de grafieken van f en g weergegeven.
figuur 2$$, 'inline'),
  ('fe62649b-8cb5-45d0-816b-d7cd5e2de1ff', '0cfe98ed-2dbd-4d03-b3a7-7fc23b2abb92', $$middelste snijpunt van g met x-as in O; A en B overige snijpunten van f met x-as, te berekenen met g$$,
   $$wiskunde-b-havo-2023-ii-een-translatie-en-snijpunten-met-de-x-as-context6.png$$,
   $$Het middelste snijpunt van de grafiek van g met de x-as ligt in de oorsprong. De grafiek van f heeft behalve punt M nog twee snijpunten met de x-as: het punt A en het punt B. De coördinaten van die snijpunten zijn met de functie f moeilijk te berekenen. Met behulp van de functie g zijn de coördinaten van deze snijpunten wel te berekenen.$$, 'inline'),
  ('71d65804-522a-4cda-8ec1-1ab8fd71b9d8', 'fb0d5f45-a3ec-4a7d-a74b-5985f8dfec41', $$shovel: bak met zand wordt gekanteld$$,
   $$wiskunde-b-havo-2023-ii-shovel-context1.png$$,
   $$Een shovel is een machine om zand mee te verplaatsen. In de bak van een shovel zit zand. Om het zand te storten, wordt de bak gekanteld.$$, 'inline'),
  ('dad5f2f6-9879-4505-9835-48204aa23f4c', 'fb0d5f45-a3ec-4a7d-a74b-5985f8dfec41', $$beginsituatie: AB = 1,50 m, ED = 1,80 m, BD = 0,25 m; A 0,30 m rechts van en 0,25 m boven E; ∠AED = 39,8°; figuur 1$$,
   $$wiskunde-b-havo-2023-ii-shovel-context2.png$$,
   $$In figuur 1 staat de beginsituatie. In deze beginsituatie zijn de bovenrand van de bak en de armen AB en ED horizontaal. Punt B ligt loodrecht boven punt D.
Verder geldt in de beginsituatie: − AB = 1,50 m, ED = 1,80 m en BD = 0,25 m; − A bevindt zich 0,30 m rechts van E en 0,25 m boven E; − ∠AED = 39,8°.
figuur 1 beginsituatie$$, 'inline'),
  ('53f6844e-a05e-4b1b-992e-cd6371275dcd', 'fb0d5f45-a3ec-4a7d-a74b-5985f8dfec41', $$gekantelde situatie: B, D, E vast, AB 10 cm langer, AE gelijk; figuur 2$$,
   $$wiskunde-b-havo-2023-ii-shovel-context3.png$$,
   $$In figuur 2 staat de situatie als de bak enigszins gekanteld is. Bij het kantelen blijven de punten B, D en E op hun plek. Door de buis bij A uit te schuiven, wordt AB 10 centimeter langer gemaakt. De afstand AE verandert niet. Hierdoor draait punt A om punt E heen. Arm AB loopt dan niet meer horizontaal en ∠AED wordt groter.
figuur 2 enigszins gekanteld$$, 'inline'),
  ('5b965180-80c7-4eef-8169-a369f2ad1a98', 'fb0d5f45-a3ec-4a7d-a74b-5985f8dfec41', $$op de uitwerkbijlage staat figuur 2 met vierhoek AEDB$$,
   $$wiskunde-b-havo-2023-ii-shovel-context4.png$$,
   $$Op de uitwerkbijlage is figuur 2 met de vierhoek AEDB weergegeven.$$, 'inline'),
  ('add88f6d-d657-46e1-b3bc-05fe469ed820', 'fb0d5f45-a3ec-4a7d-a74b-5985f8dfec41', $$uitwerkbijlage vraag 13: figuur 2 met vierhoek AEDB$$,
   $$wiskunde-b-havo-2023-ii-shovel-context5.png$$,
   $$13
(uitwerkbijlage: figuur 2 met de vierhoek AEDB)$$, 'uitwerkbijlage'),
  ('8e9317b1-3f91-4079-9813-89a571e8c441', 'f0b0f838-1b21-4068-85b4-540777d4897e', $$f(x) = 3 + 3sin(½πx); A met x-coördinaat ⅓, B met dezelfde y-coördinaat, T top van f$$,
   $$wiskunde-b-havo-2023-ii-sinusoide-en-parabool-context1.png$$,
   $$De functie f wordt gegeven door f(x) = 3 + 3sin(½πx). In de figuur is een deel van de grafiek van f weergegeven. De grafiek van deze functie gaan we in twee delen benaderen, namelijk met een deel van een parabool en met een lijnstuk.
Het punt A met x-coördinaat ⅓ ligt op de grafiek van f. Het punt B met dezelfde y-coördinaat als A ligt ook op de grafiek van f. Het punt T is de top van de grafiek van f. Zie de figuur.$$, 'inline'),
  ('5a524dfe-8f72-4d05-a298-7b4bfe1f058e', 'f0b0f838-1b21-4068-85b4-540777d4897e', $$figuur; parabool door A, T en B: y = −3⅜x² + 6¾x + 2⅝$$,
   $$wiskunde-b-havo-2023-ii-sinusoide-en-parabool-context2.png$$,
   $$figuur
Het deel van de sinusoïde tussen de punten A en B is te benaderen door de parabool die door de punten A, T en B gaat.
Een vergelijking van deze parabool is y = −3⅜x² + 6¾x + 2⅝.$$, 'inline'),
  ('b031b7f7-7e78-45e3-b2ad-6830c00af77b', 'f0b0f838-1b21-4068-85b4-540777d4897e', $$S snijpunt van f met y-as; lijnstuk SA: y = 4½x + 3$$,
   $$wiskunde-b-havo-2023-ii-sinusoide-en-parabool-context3.png$$,
   $$De grafiek van f snijdt de y-as in het punt S. Het deel van de sinusoïde tussen de punten S en A is te benaderen door een lijnstuk met vergelijking y = 4½x + 3. Dit lijnstuk gaat door de punten S en A.$$, 'inline'),
  ('a0d64d59-a5e7-4031-aad2-4e072ef7acb9', 'f0b0f838-1b21-4068-85b4-540777d4897e', $$goede benadering: geen knik in A, helling lijnstuk SA gelijk aan helling parabool$$,
   $$wiskunde-b-havo-2023-ii-sinusoide-en-parabool-context4.png$$,
   $$De benadering van de sinusoïde tussen de punten S en B bestaat nu uit twee delen: het lijnstuk SA en het deel van de parabool door A, T en B. Als er in punt A geen knik is, noemen we dit een goede benadering. Dat houdt in dat in A de helling van het lijnstuk SA gelijk is aan de helling van de parabool.$$, 'inline'),
  ('492344c3-04dc-4fb3-8528-108c617a729a', '68035372-f6f1-40eb-9ef7-cdc896f886fa', $$lijn l: y = ½x; k ontstaat door l één omhoog te schuiven; P onder l op afstand 3 van l; figuur$$,
   $$wiskunde-b-havo-2023-ii-afstand-tussen-lijnen-en-punt-context1.png$$,
   $$De lijn l wordt gegeven door de vergelijking y = ½x. De lijn k ontstaat door l één recht omhoog te schuiven. Het punt P bevindt zich onder l.
De afstand tussen l en P is 3. Zie de figuur.
figuur$$, 'inline'),
  ('0009854d-9a66-4a49-b3a4-9ca67ae0f69c', 'd0fadece-930c-40d9-9ca4-30c4139009a0', $$f(x) = 3 · 1,12ˣ + 5sin(2π(x + ¼)) = g(x) + h(x) met g(x) = 3 · 1,12ˣ en h(x) = 5sin(2π(x + ¼))$$,
   $$wiskunde-b-havo-2023-ii-dalen-stijgen-en-stijgen-context1.png$$,
   $$De functie f wordt gegeven door f(x) = 3 · 1,12ˣ + 5sin(2π(x + ¼)).
De functie f is de som van de exponentiële functie g, gegeven door g(x) = 3 · 1,12ˣ, en de periodieke functie h, gegeven door h(x) = 5sin(2π(x + ¼)).$$, 'inline'),
  ('dabb4346-dfa6-4464-8ed8-e369db7001eb', 'd0fadece-930c-40d9-9ca4-30c4139009a0', $$figuur 1: grafieken van f en h met punten A en B$$,
   $$wiskunde-b-havo-2023-ii-dalen-stijgen-en-stijgen-context2.png$$,
   $$In figuur 1 zijn voor x ≥ 0 de grafieken van f en h weergegeven met daarop de punten A en B.
figuur 1$$, 'inline'),
  ('d3840988-7413-4621-b25a-5064a437daa5', 'd0fadece-930c-40d9-9ca4-30c4139009a0', $$A 14e minimum van f (x ≈ 13,492), B 14e minimum van h; lijken dezelfde x-coördinaat te hebben$$,
   $$wiskunde-b-havo-2023-ii-dalen-stijgen-en-stijgen-context3.png$$,
   $$De functie h heeft maxima en minima. Hierdoor heeft de functie f ook maxima en minima.
Geteld vanaf de y-as wordt in punt A het 14e minimum van f bereikt en in punt B het 14e minimum van h.
De x-coördinaat van A is afgerond op drie decimalen 13,492.
Het lijkt alsof de x-coördinaten van A en B gelijk zijn.$$, 'inline'),
  ('f9392f6f-e080-413f-8578-38646779b088', 'd0fadece-930c-40d9-9ca4-30c4139009a0', $$horizontale lijn y = f(0) snijdt de grafiek van f meerdere keren; figuur 2$$,
   $$wiskunde-b-havo-2023-ii-dalen-stijgen-en-stijgen-context4.png$$,
   $$Het snijpunt van de grafiek van f met de y-as is (0, f(0)) en dus is de vergelijking van de horizontale lijn door dit punt y = f(0). Voor x > 0 zal de grafiek van f de lijn met vergelijking y = f(0) op meerdere plaatsen snijden. Zie figuur 2.
figuur 2$$, 'inline'),
  ('87370159-f18b-471f-8c28-9aabe93f22b1', 'd0fadece-930c-40d9-9ca4-30c4139009a0', $$laatste snijpunt ligt links van A$$,
   $$wiskunde-b-havo-2023-ii-dalen-stijgen-en-stijgen-context5.png$$,
   $$Vanaf een bepaalde waarde van x snijden de grafiek van f en de lijn elkaar niet meer. Het snijpunt met de grootste x-coördinaat bevindt zich links van punt A.$$, 'inline'),
  ('ac7ed5c6-915d-4a38-9bca-4341700227d6', 'd0fadece-930c-40d9-9ca4-30c4139009a0', $$laatste twee dalingen in [38, 40]; P punt met sterkste daling op het laatste dalende stuk; figuur 3$$,
   $$wiskunde-b-havo-2023-ii-dalen-stijgen-en-stijgen-context6.png$$,
   $$figuur 3
In eerste instantie is de grafiek van f afwisselend dalend en stijgend. Vanaf een bepaalde waarde van x is de grafiek van f alleen nog maar stijgend. De laatste twee dalingen vinden in het interval [38, 40] plaats.
Tijdens elke daling van hoogste naar laagste punt is er een punt op de grafiek van f waar de grafiek het sterkst daalt. In zo’n punt is de helling op dat dalende stuk dus minimaal.
Op het laatste dalende stuk is dat in het punt P. Zie figuur 3.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('e83dad68-fa6c-4f78-863d-a37cf63d8e5a', '6b53bed4-b795-4ffe-a5ad-48eeffb0f7a7', 1,
   '[{"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Standaardfuncties"}]'::jsonb,
   '["wortelfunctie", "formule invullen", "eenheden omrekenen", "afronden"]'::jsonb,
   $$Een waarde invullen in een wortelformule en het resultaat omrekenen naar een andere eenheid.$$,
